import {sceneDefaults,applyLayout} from './scene-layout.js';
// Localhost-only authoring tools; never loaded on the public hostname.
export function mountSceneEditor(THREE,entries,{canvas,camera,scene}){
 if(!['localhost','127.0.0.1','[::1]'].includes(location.hostname))return;
 const key='weiyi-scene-editor-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}');}catch{}
 const defaults=()=>({x:0,y:0,z:0,size:1,rx:0,ry:0,rz:0,color:'',hidden:false});
 const state=entries.map(e=>({...defaults(),...sceneDefaults[e.id],...(saved?.[e.id]||{})}));
 function apply(i){applyLayout(entries,state,i);}
 entries.forEach((_,i)=>apply(i));
 const panel=document.createElement('aside');panel.className='local-scene-editor';panel.innerHTML=`<button type="button" class="editor-toggle" aria-expanded="false">场景编辑 · 仅本地</button><div class="editor-body" hidden><h2>场景编辑</h2><p>位置为相对默认值；Z 越大越靠近镜头。展开面板后可直接点击植物选中；金色线框标示当前物件。</p><label>选择物件<select aria-label="选择物件"></select></label><div class="editor-fields"></div><div class="editor-actions"><button type="button" data-action="save">保存</button><button type="button" data-action="reset">恢复当前默认</button><button type="button" data-action="reset-all">恢复全部默认</button></div><p role="status"></p><p>保存仅影响本机当前浏览器，不会修改网站文件或发布。</p></div>`;
 const style=document.createElement('style');style.textContent='.local-scene-editor{position:fixed;right:16px;bottom:16px;z-index:10000;width:min(310px,calc(100vw - 32px));font:13px/1.5 Arial;color:#ddd;background:#26322f;border:1px solid #8a9a8f;box-shadow:0 5px 25px #0003}.local-scene-editor button,.local-scene-editor select,.local-scene-editor input{font:inherit}.local-scene-editor button{padding:7px 10px;background:#354740;color:#fff;border:1px solid #788c80;cursor:pointer}.editor-toggle{width:100%;text-align:left}.editor-body{padding:14px;max-height:68vh;overflow:auto}.editor-body h2{font-size:16px;margin:0}.editor-body p{font-size:11px;color:#bbc9c0}.editor-body label{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:8px 0}.editor-body input{width:90px}.editor-body select{max-width:190px}.editor-actions{display:flex;gap:5px;flex-wrap:wrap;margin-top:14px}';document.head.append(style);document.body.append(panel);
 // Drag the title bar; keep the panel reachable at every viewport size.
 let panelDrag=null,movedPanel=false;const handle=panel.querySelector('.editor-toggle');handle.style.touchAction='none';handle.style.cursor='move';
 handle.addEventListener('pointerdown',e=>{const r=panel.getBoundingClientRect();panelDrag={x:e.clientX,y:e.clientY,left:r.left,top:r.top};movedPanel=false;handle.setPointerCapture(e.pointerId);});
 handle.addEventListener('pointermove',e=>{if(!panelDrag)return;const dx=e.clientX-panelDrag.x,dy=e.clientY-panelDrag.y;if(Math.hypot(dx,dy)>4)movedPanel=true;if(!movedPanel)return;panel.style.right='auto';panel.style.bottom='auto';panel.style.left=Math.max(0,Math.min(innerWidth-panel.offsetWidth,panelDrag.left+dx))+'px';panel.style.top=Math.max(0,Math.min(innerHeight-40,panelDrag.top+dy))+'px';});
 handle.addEventListener('pointerup',()=>panelDrag=null);handle.addEventListener('pointercancel',()=>panelDrag=null);handle.addEventListener('click',e=>{if(movedPanel){e.stopImmediatePropagation();movedPanel=false;}},true);
 const exportButton=document.createElement('button');exportButton.type='button';exportButton.textContent='查看已保存配置';panel.querySelector('.editor-actions').append(exportButton);exportButton.onclick=()=>{let output=panel.querySelector('.editor-export');if(!output){output=document.createElement('textarea');output.className='editor-export';output.readOnly=true;output.setAttribute('aria-label','已保存场景配置');output.style.cssText='width:100%;height:100px';panel.querySelector('.editor-body').append(output);}output.value=localStorage.getItem(key)||'{}';};
 const select=panel.querySelector('select'),fields=panel.querySelector('.editor-fields'),status=panel.querySelector('[role=status]');entries.forEach((e,i)=>select.add(new Option(e.name,String(i))));let current=0;

 let helper=null;
 function highlight(){if(helper){scene.remove(helper);helper.geometry.dispose();helper.material.dispose();helper=null;}if(panel.querySelector('.editor-body').hidden)return;helper=new THREE.BoxHelper(entries[current].object,0xd3b16d);helper.material.depthTest=false;helper.material.transparent=true;helper.material.opacity=.8;helper.renderOrder=100;helper.raycast=()=>{};scene.add(helper);}
 const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let down=null;
 canvas.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY};},true);
 canvas.addEventListener('pointerup',e=>{
  if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>5||panel.querySelector('.editor-body').hidden){down=null;return;}down=null;
  const rect=canvas.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,camera);const hits=[];
  entries.forEach((entry,index)=>{if(!entry.plant)return;let visible=true;for(let p=entry.object;p;p=p.parent)if(!p.visible)visible=false;if(!visible)return;entry.object.traverse(o=>{if(!o.isMesh)return;const found=[];THREE.Mesh.prototype.raycast.call(o,ray,found);found.forEach(hit=>hits.push({...hit,index}));});});
  hits.sort((a,b)=>a.distance-b.distance);if(hits.length){current=hits[0].index;render();status.textContent='已选中 '+entries[current].name;e.stopImmediatePropagation();canvas.dispatchEvent(new Event('pointercancel'));}
 },true);
 function render(){entries.forEach((entry,i)=>select.options[i].textContent=entry.name+(entry.plant&&state[i].hidden?'（已隐藏）':''));fields.replaceChildren();select.value=String(current);highlight();const e=entries[current];for(const [key,label,min,max,step] of [['x','左右 X',-12,12,.1],['y','上下 Y',-12,12,.1],['z','前后 Z',-12,12,.1],...(e.plant?[['size','大小',.2,3,.05],['rx','俯仰角',-180,180,5],['ry','水平旋转',-180,180,5],['rz','倾斜角',-180,180,5]]:[])]){const row=document.createElement('label');row.textContent=label;const input=document.createElement('input');input.type='number';input.min=min;input.max=max;input.step=step;input.value=state[current][key];input.setAttribute('aria-label',label);input.addEventListener('input',()=>{if(!input.validity.valid)return;state[current][key]=Number(input.value);apply(current);status.textContent='未保存';});row.append(input);fields.append(row);}if(e.plant){const toggle=document.createElement('button');toggle.type='button';toggle.textContent=state[current].hidden?'恢复显示这株植物':'隐藏这株植物';toggle.onclick=()=>{state[current].hidden=!state[current].hidden;apply(current);render();status.textContent='显示状态已更改，点击保存可记住';};fields.append(toggle);const row=document.createElement('label');row.textContent='植物颜色';const input=document.createElement('input');input.type='color';input.value=state[current].color||'#699581';input.addEventListener('input',()=>{state[current].color=input.value;apply(current);status.textContent='未保存';});row.append(input);fields.append(row);}}
 select.onchange=()=>{current=Number(select.value);render();};panel.querySelector('.editor-toggle').onclick=e=>{const body=panel.querySelector('.editor-body');body.hidden=!body.hidden;e.currentTarget.setAttribute('aria-expanded',String(!body.hidden));highlight();};
 panel.querySelector('[data-action=save]').onclick=()=>{try{localStorage.setItem(key,JSON.stringify(Object.fromEntries(state.map((s,i)=>[entries[i].id,s]))));status.textContent='已保存在当前浏览器';}catch{status.textContent='无法保存：浏览器存储不可用';}};
 panel.querySelector('[data-action=reset]').onclick=()=>{state[current]={...defaults(),...sceneDefaults[entries[current].id]};apply(current);render();status.textContent='已恢复当前物件，点击保存可记住';};
 panel.querySelector('[data-action="reset-all"]').onclick=()=>{entries.forEach((_,i)=>{state[i]={...defaults(),...sceneDefaults[entries[i].id]};apply(i);});try{localStorage.removeItem(key);}catch{}render();status.textContent='已恢复全部默认并清除保存';};render();
 return {update(){if(helper){helper.update();let visible=true;for(let p=entries[current].object;p;p=p.parent)if(!p.visible)visible=false;helper.visible=visible;}}};
}

